      if (contentType.includes('pdf')) return 'fa fa-file-pdf-o';
      if (contentType.includes('word')) return 'fa fa-file-word-o';
      if (contentType.includes('excel') || contentType.includes('spreadsheet')) return 'fa fa-file-excel-o';
      if (contentType.includes('powerpoint') || contentType.includes('presentation')) return 'fa fa-file-powerpoint-o';
      if (contentType.includes('zip') || contentType.includes('compressed') || contentType.includes('archive')) return 'fa fa-file-archive-o';
      if (contentType.includes('text') || contentType.includes('plain')) return 'fa fa-file-text-o';
      if (contentType.includes('html') || contentType.includes('xml')) return 'fa fa-file-code-o';
      if (contentType.includes('javascript')) return 'fa fa-file-code-o javascript-icon';

      // 根据扩展名判断（更详细的映射）
      const iconMap = {
